from lib import *
S = SS('p13')
steps = [
    step("11 种服务器行为 → requests 的异常。连接阶段:没人监听 → ConnectionError(… → NewConnectionError → ConnectionRefusedError,[Errno 61])。服务器读完请求后礼貌关闭(FIN)→ ProtocolError → RemoteDisconnected(Remote end closed connection without response);不读请求就关(缓冲区有未读数据,系统发 RST)或 SO_LINGER=0 → ConnectionResetError([Errno 54])。响应不合规:不是 HTTP → BadStatusLine;状态码不是数字 → BadStatusLine → ValueError;一条响应头 70000 字节 → LineTooLong(超过 65536 字节);150 个响应头 → HTTPException(超过 100 个)。响应体中断:只发 100/1000 字节就关闭或发 RST → ChunkedEncodingError。而只发了半截响应头就关闭的那次没有报错:r.status_code=200、响应头为空、r.content 为空。", t=tl(S(1)), done=lidx(S(1), '没有任何服务在监听', '读完并正常关闭连接(FIN)', '请求字节到达后', '读完请求后,设 SO_LINGER=0'), mark=lidx(S(1), '只发了半截响应头就关闭', '细看', 'Content-Length: 1000 只发 100 字节就关闭', 'Content-Length: 1000 发 100 字节后发 RST'), kv=KV([['FIN 关闭', 'RemoteDisconnected'], ['RST 重置', 'ConnectionResetError'], ['半截响应头', '不报错:200 + 空头 + 空体']], ['半截响应头'])),
    step("协议不匹配的三种情形:https:// 去连明文 HTTP 服务器(服务器回了一个明文的 400)→ SSLError(内部 [SSL: WRONG_VERSION_NUMBER] wrong version number);http:// 去连 TLS 服务器 → ConnectionError(ProtocolError → ConnectionResetError,[Errno 54]);自签名证书且 verify=True → SSLError(SSLCertVerificationError:CERTIFICATE_VERIFY_FAILED)。三个都能被 except ConnectionError 抓到(是/否 里的“是”),都不是 Timeout。", t=tl(S(2)), done=lidx(S(2), 'https:// 去连明文 HTTP 服务器', 'https:// 连自签名证书'), mark=lidx(S(2), 'http:// 去连一个 TLS 服务器'), kv=KV([['https 连明文端口', 'SSLError WRONG_VERSION_NUMBER'], ['http 连 TLS 端口', 'ConnectionResetError'], ['自签名 + verify=True', 'SSLError CERTIFICATE_VERIFY_FAILED']], ['https 连明文端口'])),
    step("看类的继承关系就明白哪些异常能被一个 except 抓到:ConnectTimeout → ConnectionError → Timeout;ReadTimeout → Timeout(不是 ConnectionError);SSLError 和 ProxyError 都继承 ConnectionError;ChunkedEncodingError → RequestException(既不是 ConnectionError,也不是 Timeout),所以响应体阶段的断开不会被 except ConnectionError 抓到;ContentDecodingError、TooManyRedirects 也各自独立。想抓全部网络层失败,要捕获更宽的 RequestException。", t=tl(S(3)), done=lidx(S(3), 'ConnectTimeout:', 'SSLError:', 'ProxyError:'), mark=lidx(S(3), 'ChunkedEncodingError:', 'ReadTimeout:'), kv=KV([['ConnectionError 的子类', 'ConnectTimeout、SSLError、ProxyError'], ['不是它的子类', 'ReadTimeout、ChunkedEncodingError'], ['最宽的', 'RequestException']], ['不是它的子类'])),
]
A = mkartp('p13', 13, '爬虫,requests,异常,ConnectionError,RemoteDisconnected,ConnectionResetError,ChunkedEncodingError,SSLError,Python,真实验证,动画演示',
    '用纯套接字服务器制造十几种连接异常,看 requests 抛什么:FIN 关闭是 RemoteDisconnected、RST 是 ConnectionResetError、没人监听是 ConnectionRefusedError,全部包成 ConnectionError;响应体阶段的断开是 ChunkedEncodingError,不是 ConnectionError;只发半截响应头就关闭时 requests 不报错,返回 200、空头、空体。',
    '爬虫日志里最常见的错误是一长串“Connection aborted”“Max retries exceeded”。这篇用我写的套接字服务器逐种制造:对端礼貌地关、直接重置、回了乱码、响应头太多、半截响应,看 requests 到底抛什么,最里层的原因是什么,又会不会被 except ConnectionError 接住。',
    [('FIN / RST', '对端礼貌关闭是 RemoteDisconnected,被重置是 ConnectionResetError'), ('200 + 空', '只发半截响应头就断开时,requests 不报错,返回 200、空响应头、空内容'), ('否 / 否', '响应体阶段的 ChunkedEncodingError 既不是 ConnectionError 也不是 Timeout')],
    [('服务器行为 → requests 异常', '<p>连接与响应头阶段的异常对外都是 <code>requests.ConnectionError</code>,要看内部链最里层才知道原因:没人监听是 <code>ConnectionRefusedError</code>;服务器读完请求后正常关闭(FIN)是 <code>RemoteDisconnected</code>;关闭时缓冲区里有未读数据或设了 <code>SO_LINGER=0</code>(RST)是 <code>ConnectionResetError</code>。第 4 篇里的竞态就是 <code>RemoteDisconnected</code>。</p><p>响应不合规时:不是 HTTP 是 <code>BadStatusLine</code>;一条响应头超过 65536 字节是 <code>LineTooLong</code>;响应头超过 100 个是 <code>HTTPException</code>。响应体读到一半断开(长度不足或被重置)是 <code>ChunkedEncodingError</code>。</p><p>最值得注意的是半截响应头:服务器发了 <code>HTTP/1.1 200 OK\\r\\nContent-Le</code> 就关闭,requests 返回 200、空头、空内容,没有任何异常。爬虫如果只看状态码,就会把这种半截响应当成功。</p>'),
     ('协议不匹配', '<p>https 地址连到明文端口得到 <code>SSLError</code>(<code>WRONG_VERSION_NUMBER</code>);http 地址连到 TLS 端口,服务器看到的是乱码,这里得到 <code>ConnectionResetError</code>;自签名证书加 <code>verify=True</code> 是 <code>SSLError</code>(<code>CERTIFICATE_VERIFY_FAILED</code>)。这三种都是 <code>ConnectionError</code> 的子类。</p>'),
     ('哪个 except 能抓到', '<p><code>ConnectTimeout</code>、<code>SSLError</code>、<code>ProxyError</code> 继承自 <code>ConnectionError</code>;<code>ReadTimeout</code> 只继承 <code>Timeout</code>;<code>ChunkedEncodingError</code> 既不是 <code>ConnectionError</code> 也不是 <code>Timeout</code>。所以只写 <code>except ConnectionError</code> 会漏掉读超时和响应体阶段的断开;想统一处理要捕获 <code>requests.RequestException</code>。</p>')],
    steps,
    [ENV_P + '。服务器是 RawSrv:收到请求后按场景直接用套接字发送字节、关闭或用 SO_LINGER=0 重置;异常链通过沿着异常的 args、reason、__cause__ 逐层展开得到;“ConnectionError / Timeout”是对抛出的异常做 isinstance 判断',
     '没有验证:Linux、Windows 上同样场景下的异常类(macOS 上 RST 对应 Errno 54,Linux 是 Errno 104);带重试(Retry)时的行为;aiohttp 和 httpx 的对应异常(aiohttp 的 ServerDisconnectedError、ClientPayloadError 等没有测);半截响应头“成功”这一现象在其它 Python/urllib3 版本里是否同样出现;HTTP/2 下的连接异常;代理场景下的连接异常'],
    '连接异常')
